using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = CreateReportingConfiguration();
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var storage = new DiskBasedReportingStorage(storagePath: "eval-results");

        var evaluators = new IEvaluator[]
        {
            new RelevanceTruthAndCompletenessEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        return DiskBasedReportingConfiguration.Create(storage, evaluators);
    }

    [TestMethod]
    public async Task Chat_responds_relevantly()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_responds_relevantly));

        var chatClient = scenario.ServiceProvider?.GetService<IChatClient>()
            ?? CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await scenario.EvaluateAsync(
            messages,
            response,
            additionalContext:
            [
                new EvaluationContext("ground_truth", "The capital of France is Paris.")
            ]);

        // Validate that evaluation metrics meet thresholds
        foreach (var metric in scenario.GetAllMetrics())
        {
            if (metric is NumericMetric numericMetric)
            {
                Assert.IsTrue(
                    numericMetric.Value >= 3,
                    $"Metric '{metric.Name}' scored {numericMetric.Value}, expected >= 3");
            }
        }
    }

    [TestMethod]
    public async Task Chat_responds_coherently_to_multiturn()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_responds_coherently_to_multiturn));

        var chatClient = scenario.ServiceProvider?.GetService<IChatClient>()
            ?? CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I'm planning a trip to Japan. What should I know?"),
        };

        var response1 = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response1.Messages);

        messages.Add(new ChatMessage(ChatRole.User, "What about the food there?"));
        var response2 = await chatClient.GetResponseAsync(messages);

        await scenario.EvaluateAsync(messages, response2);

        foreach (var metric in scenario.GetAllMetrics())
        {
            if (metric is NumericMetric numericMetric)
            {
                Assert.IsTrue(
                    numericMetric.Value >= 3,
                    $"Metric '{metric.Name}' scored {numericMetric.Value}, expected >= 3");
            }
        }
    }

    private static IChatClient CreateChatClient()
    {
        // Falls back to environment-configured endpoint when not running via Aspire
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException(
                "Set AZURE_OPENAI_ENDPOINT or run via Aspire hosting.");

        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY") ?? "";

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();
    }
}

